#rf-root,.hf-root{--x3:#414b5a;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;}.cam{position:absolute;inset:0;animation:st-cam 6s linear both;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.bd-grid{position:absolute;inset:0;background-image:linear-gradient(color-mix(in srgb,var(--rf-text) 6%,transparent) 2px,transparent 2px),linear-gradient(90deg,color-mix(in srgb,var(--rf-text) 6%,transparent) 2px,transparent 2px);background-size:108px 108px;background-position:-2px -2px}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}.tx-out{transform:translateY(101%);animation:tx-out 0.5s cubic-bezier(.76,0,.24,1) 5.5s both}@keyframes tx-out{to{transform:translateY(0)}}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
@keyframes st-pushin{from{transform:translateX(100%)}to{transform:none}}
@keyframes st-pushout{to{transform:translateX(-100%)}}
@keyframes st-zoomin{from{transform:scale(.92);opacity:0}to{transform:none;opacity:1}}
@keyframes st-zoomout{to{transform:scale(1.08);opacity:0}}
@keyframes st-fadein{from{opacity:0}to{opacity:1}}
@keyframes st-fadeout{to{opacity:0}}.rise{animation:k-rise .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-rise{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
.pop{animation:k-pop .7s cubic-bezier(.16,1,.3,1) both}@keyframes k-pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.slide-l{animation:k-sl .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sl{from{opacity:0;transform:translateX(-80px)}to{opacity:1;transform:none}}
.slide-r{animation:k-sr .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sr{from{opacity:0;transform:translateX(80px)}to{opacity:1;transform:none}}
.fade{animation:k-fade .8s ease-out both}@keyframes k-fade{from{opacity:0}to{opacity:1}}.mk-l{display:block}.mk-w{display:inline-block;overflow:hidden;vertical-align:top;padding:0 .02em .08em;margin-bottom:-.08em}
.mk-w>span{display:inline-block;animation:mk-up 0.9s cubic-bezier(.16,1,.3,1) both}
@keyframes mk-up{from{transform:translateY(105%)}to{transform:none}}.cd-hd{position:absolute;left:90px;right:90px;top:280px;font-size:88px;font-weight:var(--rf-heading-weight);letter-spacing:-.04em;line-height:1}
.ed{position:absolute;left:60px;right:60px;top:600px;border-radius:32px;background:color-mix(in srgb,var(--rf-bg) 70%,#000);box-shadow:0 0 0 2px color-mix(in srgb,var(--rf-text) 10%,transparent);overflow:hidden;animation:k-rise .9s cubic-bezier(.16,1,.3,1) 0s both}
.ed-bar{height:70px;display:flex;align-items:center;gap:12px;padding:0 28px;background:color-mix(in srgb,var(--rf-text) 6%,transparent)}
.ed-bar i{width:20px;height:20px;border-radius:50%;background:#ff5f57}.ed-bar i:nth-child(2){background:#febc2e}.ed-bar i:nth-child(3){background:#28c840}
.ed-bar span{margin-left:20px;font:500 26px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-muted)}
.ed-code{padding:34px 34px 40px;font:500 33px/1.65 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-text)}
.ln{display:flex;white-space:pre}
.no{width:56px;flex:none;color:color-mix(in srgb,var(--rf-text) 30%,transparent)}
.ty{display:inline-block;overflow:hidden;width:calc(var(--ch) * 1ch + 2px);animation-name:ty;animation-fill-mode:both}
@keyframes ty{from{width:0}}
.k{font-style:normal;color:var(--rf-accent)}.c{font-style:normal;color:color-mix(in srgb,var(--rf-text) 42%,transparent)}.st{font-style:normal;color:color-mix(in srgb,var(--rf-accent) 55%,var(--rf-text))}
.term{display:flex;align-items:center;gap:16px;margin:0 34px 34px;padding:26px 30px;border-radius:20px;background:color-mix(in srgb,var(--rf-text) 6%,transparent);font:600 30px/1.3 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-text)}
.pr{color:var(--rf-muted)}.ok{margin-left:auto;color:var(--rf-accent);display:flex}

